//TD 10234
ta_int32 RadioSession::makeCall(const std::string & destTSI,ECallType callType,bool isFullDuplex, TA_IRS_App::ECallPriority priority,bool hook,std::string sessionId, bool isInvisibleToGUIApps, ta_int32 locationKey)// //TD19783
{
	FUNCTION_ENTRY("makeCall");

	RadioMethodSetupCall::ECallType type;
	ECallCategory  category;
	switch (callType)
	{
		case SingleCall:
			 type = RadioMethodSetupCall::SINGLE_CALL;
			 category = isFullDuplex?FullDuplex:HalfDuplex;
			 break;
		case GroupUnacknowledgeCall: 
			 type = RadioMethodSetupCall::GROUP_UNACKNOWLEDGE;
			 category = HalfDuplex;
			 break;
		case GroupAcknowledgeCall: 
			 type = RadioMethodSetupCall::GROUP_ACKNOWLEDGE;
			 category = HalfDuplex;
			 break;
		case GroupBroadcastCall: 
			 type = RadioMethodSetupCall::BROADCAST;
			 category = HalfDuplex;
			 break;

		default:
			TA_ASSERT(false,"Invalid call type.");
	};

	// Get a new call reference (to be deleted when the call disconnects)
	RadioReference callReference;
	callReference = getNewReference(RadioMethodNewReference::CALL_REFERENCE);

	// Setup the call (note we might get an unsolicited CallStatus event in addition to the Setup call event)
	RadioMethodSetupCall   setupMethod(getValidSessionRef(),callReference);
	setupMethod.setCallDestination(destTSI);
	setupMethod.setCallType(type);
	setupMethod.setFullDuplex(isFullDuplex);

    //TD14696
    //setupMethod.setCallPriority(isEmergency?RadioMethodSetupCall::EmergencyPriority:RadioMethodSetupCall::LowPriority);              
    if  (priority == DefaultNormalPriority) 
    {
        setupMethod.setCallPriority(m_DefaultNormalCallPriority);
    }
    else if (priority == DefaultEmergencyPriority) 
    {
        setupMethod.setCallPriority(m_DefaultEmergencyCallPriority);
    }
    else
    {
        setupMethod.setCallPriority(priority); 
    }    
    //

    setupMethod.setHookBit( hook );
    if ( (callType==SingleCall) && (!isFullDuplex) )
    {
		// Do not request for TX when performing half duplex calls
        LOG_GENERIC( SourceInfo, TA_Base_Core::DebugUtil::DebugDebug, "SingleCall HalfDuplex request detected - activating REQUEST_TX" );
        setupMethod.setRequestTx(RadioMethodSetupCall::REQUEST_TX);
    }

    
	RadioEvent* reply = sendMethod(setupMethod, destTSI);
	delete reply;

    // Attach some audio to the call
    // VoiceRecorder data submitted further down
    m_radioTcpServer.getRadioResourceManager().attachAudio(getValidSessionRef(),callReference);

	// Cease TX to release PTT assignment
	if (!isFullDuplex)
	{// For Any half duplex calls
		RadioMethodCeaseTX   ceaseTXMethod(getValidSessionRef());
		ceaseTXMethod.addCallReference(callReference);
		RadioEvent* reply = sendMethod(ceaseTXMethod);
		delete reply;
	}

	// Add a new call to the stack
	CallDetailsType details;
	// CallDetailsType  details;

	details.callStatus   = Connected;
	details.callSource   = OutgoingCall;
	details.callCategory = category;  
    details.callType     = callType;
	// details.callTime     = getCurrentTime();  // set by radio

	// Get the call details from the event
	details.callID     = callReference;
	details.sessionRef = getValidSessionRef();
	details.calledTSI  = destTSI;
	details.callerTSI  = getSessionTSI();

	details.isEmergency= false;
	if (priority == DefaultEmergencyPriority)
    {
		details.isEmergency= true;
    }

	//TD 10234
    details.isInvisibleToGUIApps = isInvisibleToGUIApps;
	details.isIncludeCall = false;
	if (locationKey != 0)//TD19783
	{
		details.callerLocation =  TA_Base_Core::LocationAccessFactory::getInstance().getLocationByKey( locationKey )->getName() ;
	}
    // add call to call stack before doing any more queries
    if (callType != GroupAcknowledgeCall)
    {
        // This both looks up the caller/called details and adds to the callstack
        m_radioTcpServer.addBackgroundTask(RadioTaskFactory::createCallStackUpdateTask(&m_radioTcpServer, details, m_DefaultEmergencyCallPriority));
    }
    else
    {
        // must wait for a suitable GroupCallAck event before proceeding...
        m_radioTcpServer.addPendingGroupCallAck(details);
    }


	return callReference;

	FUNCTION_EXIT;
}

bool RadioSession::is_little_endian() const
{
	union {
		uint16_t value;
		uint8_t bytes[sizeof(uint16_t)];
	} test_endian;

	test_endian.value = 1; // Store the number 1

	// If the first byte (at the lowest memory address) is 1, it's little-endian.
	// Otherwise, it's big-endian (where the first byte would be 0 for a value of 1).
	return test_endian.bytes[0] == 1;
}

bool RadioSession::sendTextMessage(const std::string& destTSI, const std::string& message, ESdsServiceSelection serviceSelection, const std::string& sessionId, std::string& status)
{
	FUNCTION_ENTRY("sendTextMessage - internal");

	MessageListType messageList;

	MessageTextType messageText(message.begin(), message.end());
	messageList.push_back(messageText);

	FUNCTION_EXIT;
	return sendTextMessage(destTSI, messageList, serviceSelection, sessionId, status);
}

bool RadioSession::sendTextMessage(const std::string& destTSI, const TA_IRS_App::MessageListType& messages, ESdsServiceSelection serviceSelection, const std::string& sessionId, std::string& status, bool logHistory, bool encodeSDS)
{
	FUNCTION_ENTRY("sendTextMessage");

	// Change to retrieve info from local database
	TA_Base_Core::IRASubscribers* subscriber =
		TA_Base_Core::RASubscribersAccessFactory::getInstance().getSubscriberDetails(destTSI);

	if (Unknown == serviceSelection)
	{
		if (NULL != subscriber)
		{
			TA_Base_Core::IRASubscribers::SubscriberType type = subscriber->getSubscriberType();
			if (TA_Base_Core::IRASubscribers::GROUP == type ||
				TA_Base_Core::IRASubscribers::PATCH_GROUP == type)
			{
				serviceSelection = Group;
			}
			else
			{
				serviceSelection = Individual;
			}
		}
		else
		{
			RadioSessionHelper helper(getValidSessionRef(), m_radioTcpServer);
			std::string k_type = helper.getSubscriberType(destTSI);
			if (("P" == k_type) || ("G" == k_type))
			{
				serviceSelection = Group;
			}
			else
			{
				serviceSelection = Individual;
			}
		}

	}

	LOG3(SourceInfo, TA_Base_Core::DebugUtil::DebugDebug, "Sending message to TSI %s with Message List size %d, encodeSDS %s", destTSI.c_str(), messages.size(), encodeSDS ? "TRUE" : "FALSE");

	TA_IRS_Bus::Ucs2CharacterEncoding charEncoder;
	std::string strMessage;
	for (int idx = 0; idx < messages.size(); idx++)
	{
		MessageTextType textMsg = messages[idx];
		MessageTextType finalTextMsg;

		if (encodeSDS)
		{
			std::string mbsString(textMsg.begin(), textMsg.end());
			strMessage += mbsString;

			// Convert to wide string (handles Chinese characters via iconv)
			std::wstring wideString = charEncoder.convertText(mbsString);

			LOG1(SourceInfo, TA_Base_Core::DebugUtil::DebugDebug, "Enable Encoding: Processing wide string with Size %d", wideString.size());

			// Format all string to UCS-2 Big-Endian
			for (std::wstring::const_iterator textIter = wideString.begin();
				textIter != wideString.end(); ++textIter)
			{
				unsigned short value = (unsigned short)*(textIter);
				LOG1(SourceInfo, TA_Base_Core::DebugUtil::DebugDebug, "Processing wide character with value %d", value);

				unsigned char lowerByte, upperByte;

				if (is_little_endian())
				{
					upperByte = (unsigned char)(value >> 8); // retrieve the higher byte
					lowerByte = (unsigned char)(value & 0xff); // retrieve the lower byte
				}
				else
				{
					upperByte = (unsigned char)(value & 0xff); // retrieve the upper byte
					lowerByte = (unsigned char)(value >> 8); // retrieve the lower byte
				}

				// Motorola is formatted in BigEndian
				finalTextMsg.push_back(upperByte);
				finalTextMsg.push_back(lowerByte);
			}
			LOG3(SourceInfo, TA_Base_Core::DebugUtil::DebugDebug, "Sending message to TSI %s with Message Text %s, data size %d", destTSI.c_str(), mbsString.c_str(), finalTextMsg.size());
		}
		else
		{
			finalTextMsg = textMsg;
		}

		if (false == sendTextDataMessage(destTSI, finalTextMsg, serviceSelection, status, encodeSDS))
		{
			FUNCTION_EXIT;
			return false;
		}
		if (messages.size() > 1)
		{
			TA_Base_Core::Thread::sleep(1000);
		}
	}

	if (logHistory) // only log the history if set. This is to prevent history items for "data" type sds's or sds's on the ISCS session
	{
		// Add an entry into the history
		std::string identifier;
		std::string location;

		RadioSessionHelper helper(m_sessionRef, m_radioTcpServer);
		if (NULL != subscriber)
		{
			identifier = subscriber->getSubscriberName();
			location = subscriber->getLocation();
		}
		else
		{
			identifier = helper.getSubscriberName(destTSI);
			location = helper.getSubscriberAttribute(destTSI, RadioMethodQueryReference::K_ORGANISATION);
		}

		time_t currentTime = RadioHelper::getCurrentTime();

		TA_IRS_App::CallDetailsType details;
		details.callID = static_cast<ta_uint32>(-1); // No callID is applicable. Initialising to very large number to prevent clashes 
		details.callStatus = Deleted;
		details.callCategory = TextMessage;
		details.sessionRef = static_cast<ta_uint32>(-1); // No sessionRef is applicable. Initialising to very large number to prevent clashes 
		details.consoleID = m_consoleID;
		m_radioTcpServer.getRadioCallback().onCallStatusChange(details);
	}

	if (NULL != subscriber)
		delete subscriber; // release the data

	FUNCTION_EXIT;
	return true;
}

bool RadioSession::sendTextDataMessage(const std::string& destTSI, const TA_IRS_App::MessageTextType& message, ESdsServiceSelection serviceSelection, std::string& status, bool encodeSDS)
{
	FUNCTION_ENTRY("bool sendTextDataMessage()");

	// Get a new call reference (to be deleted when the call disconnects)
	RadioReference   reference;
	reference = getNewReference(RadioMethodNewReference::SDS_REFERENCE);

	RadioEvent* reply = NULL;
	{//by TLSDSTransfer
		RadioMethodTLSDSTransfer sendSDSMethod(getValidSessionRef(), reference);
		sendSDSMethod.setCalledNumber(destTSI);
		sendSDSMethod.setProtocol(SDSTL_PROT_TEXT_MESSAGING);
		sendSDSMethod.setRequestTimestampFlag(true);
		sendSDSMethod.setReceiveReceiptFlag(SDSTL_REPREQ_NONE); //to check the receive status
		sendSDSMethod.setMessage(message);

		switch (serviceSelection)
		{
		case Individual:
			sendSDSMethod.setServiceSelection(SDSTL_INDIVIDUAL);
			break;
		case Group:
			sendSDSMethod.setServiceSelection(SDSTL_GROUP);
			break;
			// this should already have been done by sendTextMessage, but handle it just in case
		case Unknown:
		default:
		{
			TA_Base_Core::IRASubscribers* subscriber =
				TA_Base_Core::RASubscribersAccessFactory::getInstance().getSubscriberDetails(destTSI);
			if (NULL != subscriber)
			{
				TA_Base_Core::IRASubscribers::SubscriberType type = subscriber->getSubscriberType();
				if (TA_Base_Core::IRASubscribers::GROUP == type ||
					TA_Base_Core::IRASubscribers::PATCH_GROUP == type)
				{
					sendSDSMethod.setServiceSelection(SDSTL_GROUP);
				}
				else
				{
					sendSDSMethod.setServiceSelection(SDSTL_INDIVIDUAL);
				}

				delete subscriber; // release the data
			}
			else
			{
				RadioSessionHelper helper(m_sessionRef, m_radioTcpServer);
				std::string k_type = helper.getSubscriberType(destTSI);
				if (("P" == k_type) || ("G" == k_type))
				{
					sendSDSMethod.setServiceSelection(SDSTL_GROUP);
				}
				else
				{
					sendSDSMethod.setServiceSelection(SDSTL_INDIVIDUAL);
				}
			}
		}
		}

		reply = sendMethod(sendSDSMethod, destTSI);
	}

	bool bStatus = false;
	if (reply == NULL) {
		status = "Can not receive the sent text message";
		LOG(SourceInfo, TA_Base_Core::DebugUtil::GenericLog, TA_Base_Core::DebugUtil::DebugInfo,
			"after Sending text message, reply event is NULL");
		FUNCTION_EXIT;
		return bStatus;
	}
	else
	{
		if (reply->getStatus() == STATUS_OK)
		{
			bStatus = true;
		}
	}
	status = reply->getTextStatus();
	delete reply;

	// Release the SDS Reference
	deleteReference(reference, RadioMethodDeleteReference::SDS_REFERENCE);

	FUNCTION_EXIT;

	return bStatus;
}

bool RadioSession::sendUserDefinedSDS(const std::string& destTSI, const TA_IRS_App::MessageListType& messages, const std::string& sessionId, std::string & status, bool logHistory/*=false*/)
{
	FUNCTION_ENTRY("sendUserDefinedSDS");
	for (MessageListType::const_iterator messageIter = messages.begin(); messageIter != messages.end(); ++messageIter)
	{
		if (false == sendUserDefinedSDSInternal(destTSI, *messageIter, status) )
		{
			FUNCTION_EXIT;
			return false;
		}
		if(messages.size() > 1)
		{
			TA_Base_Core::Thread::sleep(1000);
		}
	}

	if(logHistory) // only log the history if set. This is to prevent history items for "data" type sds's or sds's on the ISCS session
	{
		// Add an entry into the history
		TA_Base_Core::IRASubscribers* subscriber =
			TA_Base_Core::RASubscribersAccessFactory::getInstance().getSubscriberDetails(destTSI);

		std::string identifier;
		std::string location;

		RadioSessionHelper helper(m_sessionRef, m_radioTcpServer);
		if (NULL != subscriber)
		{
			identifier = subscriber->getSubscriberName();
			location = subscriber->getLocation();
		}
		else
		{
			identifier = helper.getSubscriberName(destTSI);
			location = helper.getSubscriberAttribute(destTSI, RadioMethodQueryReference::K_ORGANISATION);
		}
		time_t currentTime = RadioHelper::getCurrentTime();

		TA_IRS_App::CallDetailsType details;
		details.callID       = static_cast<ta_uint32>(-1); // No callID is applicable. Initialising to very large number to prevent clashes 
		details.callStatus   = Deleted;
		details.callCategory = TextMessage;
		details.sessionRef = static_cast<ta_uint32>(-1); // No sessionRef is applicable. Initialising to very large number to prevent clashes 
		details.consoleID = m_consoleID;
		m_radioTcpServer.getRadioCallback().onCallStatusChange(details);

		if (NULL != subscriber)
			delete subscriber;
	}

	FUNCTION_EXIT;
	return true;
}

bool RadioSession::sendUserDefinedSDSInternal(const std::string& destTSI, const TA_IRS_App::MessageTextType& message, std::string & status)
{
	FUNCTION_ENTRY("sendTextMessageExt");
	// Get a new call reference (to be deleted when the call disconnects)
	RadioReference   reference;
	reference = getNewReference(RadioMethodNewReference::SDS_REFERENCE);

	RadioEvent* reply = NULL;
	{	//by UserDefinedSDS
		RadioMethodUserDefinedSDS sendUDSDSMethod(getValidSessionRef(), reference);
		sendUDSDSMethod.setCalledNumber(destTSI);
		sendUDSDSMethod.setMessage(message);
		
		reply = sendMethod(sendUDSDSMethod, destTSI);
	}	

	bool bStatus = false;
	if (reply == NULL){
		status = "Can not receive the sent text message";
		LOG( SourceInfo, TA_Base_Core::DebugUtil::GenericLog, TA_Base_Core::DebugUtil::DebugInfo, 
			"after Sending text message, reply event is NULL");
		FUNCTION_EXIT;
		return bStatus;
	}
	else
	{
		if (reply->getStatus() == STATUS_OK)
		{
			bStatus = true;
		}
	}
	status = reply->getTextStatus();
	delete reply;

	// Release the SDS Reference
	deleteReference(reference,RadioMethodDeleteReference::SDS_REFERENCE);

	FUNCTION_EXIT;
	return bStatus;
}


std::string RadioSession::makeDynamicGroup(std::vector<std::string> destTSIs, std::string sessionId)
{
	FUNCTION_ENTRY("makeDynamicGroup");

	checkRadioFallback();

	bool dgnaFound = false;
	try
	{
		std::string strDGNASearch = "TSI='" + m_sessionDGNAITSI + "'";
		ta_uint32 dgnaResultSet = performSubscriberSearch(strDGNASearch);
		std::vector<std::string> destinationTextReferences = queryResultsAsList(dgnaResultSet, RadioMethodQueryReference::K_MEMBERS);
		deleteReference(dgnaResultSet, RadioMethodDeleteReference::SEARCH_REFERENCE);

		if (destinationTextReferences.size() != 0)
		{
			dgnaFound = true;
			LOG1(SourceInfo, TA_Base_Core::DebugUtil::DebugInfo, "Found DGNA Subscriber TSI %s", m_sessionDGNAITSI.c_str());
		}

	}
	catch (...)
	{
		LOG1(SourceInfo, TA_Base_Core::DebugUtil::DebugError, "Error Searching for DGNA Subscriber TSI %s", m_sessionDGNAITSI.c_str());
	}

	if (dgnaFound)
	{
		LOG2(SourceInfo, TA_Base_Core::DebugUtil::DebugInfo, "Updating DGNA Subscriber TSI %s with size %d", m_sessionDGNAITSI.c_str(), destTSIs.size());
		updateDynamicGroup(destTSIs, sessionId);
		return m_sessionDGNAITSI;
	}

	unsigned int iLoop;
	std::stringstream ss;
	ss << "DGNA";
	ss << atoi(m_sessionDGNAITSI.c_str());

	std::string dgnaName = ss.str();

	// Get the textual references for the destTSI's
	std::string destSearchText = "";
	for (iLoop = 0; iLoop < destTSIs.size(); iLoop++)
	{
		if (iLoop != 0) destSearchText += " OR ";
		destSearchText += "TSI='" + destTSIs.at(iLoop) + "'";
	}
	// Add our own TSI
	destSearchText += " OR TSI='" + getSessionTSI() + "'";

	ta_uint32 referenceResultSet = performSubscriberSearch(destSearchText);
	std::vector<std::string> destinationTextReferences = queryResultsAsList(referenceResultSet, RadioMethodQueryReference::K_MEMBERS);

	// New Reference
	RadioReference   newSubRef;
	newSubRef = getNewReference(RadioMethodNewReference::SUBSCRIBER_REFERENCE);

	// Determine the subscribers to remove
	std::string groupMembers = "";
	for (int idx = 0; idx < destinationTextReferences.size(); idx++)
	{
		if (groupMembers.size() > 0)
			groupMembers += ",";

		groupMembers += "+" + destinationTextReferences.at(idx);
	}

	RadioMethodChangeReference changeReferenceMethod(getValidSessionRef(), newSubRef);

	std::string targetName = dgnaName;
	bool encodeName = true;
	if (TA_Base_Core::RunParams::getInstance().isSet(RadioAgentConstants::RPARAM_LANGUAGE))
	{
		std::string lang = TA_Base_Core::RunParams::getInstance().get(RadioAgentConstants::RPARAM_LANGUAGE);
		if (lang == RadioAgentConstants::LANGUAGE_EN)
			encodeName = false;
		else
			targetName = formatString(dgnaName);
	}

	//changeReferenceMethod.createDynamicGroup(targetName, m_sessionDGNAITSI, groupMembers, encodeName);

	RadioEvent* reply = sendMethod(changeReferenceMethod);
	delete reply;
	reply = NULL;

	deleteReference(referenceResultSet, RadioMethodDeleteReference::SEARCH_REFERENCE);
	// Delete the new subscriber reference
	deleteReference(newSubRef, RadioMethodDeleteReference::SUBSCRIBER_REFERENCE);

	// release the reference
	//deleteReference(dgnaRef,RadioMethodDeleteReference::SUBSCRIBER_REFERENCE);

	FUNCTION_EXIT;
	return m_sessionDGNAITSI;
}

void RadioSession::updateDynamicGroup(std::vector<std::string> destTSIs, std::string sessionId)
{
	FUNCTION_ENTRY("makeDynamicGroup");
	// Todo: Create DGNA if reference is not found

	checkRadioFallback();

	unsigned int iLoop;

	std::stringstream ss;
	ss << "DGNA";
	ss << m_sessionDGNAITSI;

	std::string dgnaName = ss.str();
	std::string targetName = dgnaName;
	bool encodeName = true;
	if (TA_Base_Core::RunParams::getInstance().isSet(RadioAgentConstants::RPARAM_LANGUAGE))
	{
		std::string lang = TA_Base_Core::RunParams::getInstance().get(RadioAgentConstants::RPARAM_LANGUAGE);
		if (lang == RadioAgentConstants::LANGUAGE_EN)
			encodeName = false;
		else
			targetName = formatString(dgnaName);
	}

	// Get the textual references for the destTSI's
	std::string destSearchText = "";
	for (iLoop = 0; iLoop < destTSIs.size(); iLoop++)
	{
		if (iLoop != 0) destSearchText += " OR ";
		destSearchText += "TSI='" + destTSIs.at(iLoop) + "'";
	}

	// Add our own TSI
	destSearchText += " OR TSI='" + getSessionTSI() + "'";

	ta_uint32 referenceResultSet = performSubscriberSearch(destSearchText);
	std::vector<std::string> destinationTextReferences = queryResultsAsList(referenceResultSet, RadioMethodQueryReference::K_MEMBERS);
	deleteReference(referenceResultSet, RadioMethodDeleteReference::SEARCH_REFERENCE);

	// Get the DGNA reference
	referenceResultSet = performSubscriberSearch("TSI='" + std::string(m_sessionDGNAITSI) + "'");
	std::string dgnaTextRef = queryResults(referenceResultSet, RadioMethodQueryReference::K_MEMBERS);
	deleteReference(referenceResultSet, RadioMethodDeleteReference::SEARCH_REFERENCE);
	ta_uint32 dgnaRef = convertTextToSubscriberReference(dgnaTextRef);

	// Query current subscribers in dgna
	ta_uint32 groupResultSet = performSubscriberSearch("PARENT='" + std::string(m_sessionDGNAITSI) + "'"
		, RadioMethodSearchSubscribers::K_MEMBERS);
	std::vector<std::string> dgnaSubscribersTextRef = queryResultsAsList(groupResultSet, RadioMethodQueryReference::K_MEMBERS);
	deleteReference(groupResultSet, RadioMethodDeleteReference::SEARCH_REFERENCE);

	bool isSubcsribersChanged = false;
	bool isDGNANameChanged = false;
	// Check if the name change for this DGNA
	IRASubscribers* group = NULL;

	try
	{
		group = TA_Base_Core::RASubscribersAccessFactory::getInstance().getSubscriberDetails(m_sessionDGNAITSI);
		if (group->getSubscriberName() != dgnaName)
			isDGNANameChanged = true;

	}
	catch (...)
	{
		LOG1(SourceInfo, TA_Base_Core::DebugUtil::DebugError, "Unable to retrieve DGNA subscrber with TSI %s", m_sessionDGNAITSI);
	}

	if (group != 0)
		delete group;

	// Determine the subscribers to remove
	std::string changeText = "";
	for (iLoop = 0; iLoop < dgnaSubscribersTextRef.size(); iLoop++)
	{
		// Check if this subscriber is in the new dest TSI list
		if (dgnaSubscribersTextRef.at(iLoop).empty()) continue;
		if (!isPresent(dgnaSubscribersTextRef.at(iLoop), destinationTextReferences))
		{
			// No, so make sure we delete it
			if (changeText.size() > 0) changeText += ",";
			changeText += "-" + dgnaSubscribersTextRef.at(iLoop);
			isSubcsribersChanged = true;
		}
	}

	// Add any additional subscribers
	for (iLoop = 0; iLoop < destinationTextReferences.size(); iLoop++)
	{
		// Check if this subscriber is not in the existing dest TSI list
		if (destinationTextReferences.at(iLoop).empty()) continue;
		if (!isPresent(destinationTextReferences.at(iLoop), dgnaSubscribersTextRef))
		{
			// No, so make sure we add it
			if (changeText.size() > 0) changeText += ",";
			changeText += "+" + destinationTextReferences.at(iLoop);
			isSubcsribersChanged = true;
		}
	}

	// We have to check if there are changes in subscribers because
	// it will give us an error (-12) if we do a changereference and no changes in the subcribers.
	if (isDGNANameChanged)
	{
		// Update the subscriber record and name
		RadioMethodChangeReference changeReferenceMethod(getValidSessionRef(), dgnaRef);

		changeReferenceMethod.updateDynamicGroup(targetName, changeText, encodeName);
		RadioEvent* reply = sendMethod(changeReferenceMethod);
		delete reply;
		reply = NULL;
	}
	else if (isSubcsribersChanged)
	{
		// Update the subscriber record
		RadioMethodChangeReference changeReferenceMethod(getValidSessionRef(), dgnaRef);
		changeReferenceMethod.setGroupMembers(changeText);
		RadioEvent* reply = sendMethod(changeReferenceMethod);
		delete reply;
		reply = NULL;
	}

	// Delete the existing data first
	//m_radioTcpServer.getRadio().deleteDBDynaGroup(dgnaTSI);

	// Create a new one
	//m_radioTcpServer.getRadio().insertDBDynaGroup(dgnaTSI, dgnaName, destTSIs, sessionId.c_str());
	// release the reference
	//deleteReference(dgnaRef,RadioMethodDeleteReference::SUBSCRIBER_REFERENCE);

	FUNCTION_EXIT;
}

void RadioSession::deleteDynamicGroup(const char* dgnaTSI, const char* sessionID)
{
	FUNCTION_ENTRY("deleteDynamicGroup");
	checkRadioFallback();

	// Get the DGNA reference
	ta_uint32 referenceResultSet = performSubscriberSearch("TSI='" + std::string(dgnaTSI) + "'");
	std::string dgnaTextRef = queryResults(referenceResultSet, RadioMethodQueryReference::K_MEMBERS);
	deleteReference(referenceResultSet, RadioMethodDeleteReference::SEARCH_REFERENCE);
	ta_uint32 dgnaRef = convertTextToSubscriberReference(dgnaTextRef);

	// Delete the subscriber
	RadioMethodDeleteSubscriber deleleteSub(getValidSessionRef(), dgnaRef);
	RadioEvent* reply = sendMethod(deleleteSub);

	if (0 != reply)
	{
		// Delete the reply
		delete reply;
		reply = NULL;
	}

	m_radioTcpServer.getRadio().deleteDBDynaGroup(dgnaTSI);
	FUNCTION_EXIT;
}

bool isPresent(std::string text, std::vector<std::string> textList)
{
    FUNCTION_ENTRY("isPresent");
	for (unsigned int iLoop=0;iLoop<textList.size();iLoop++)
	{
		if (text==textList.at(iLoop)) return true;
	}

	FUNCTION_EXIT;
	return false;
}

void RadioSession::deassignDynamicGroup()
{
	FUNCTION_ENTRY("deassignDynamicGroup()");

    checkRadioFallback();

	// Get the DGNA reference
	ta_uint32 referenceResultSet = performSubscriberSearch("TSI='" + m_sessionDGNAITSI + "'");
    std::string dgnaTextRef = queryResults(referenceResultSet,RadioMethodQueryReference::K_MEMBERS);
	deleteReference(referenceResultSet,RadioMethodDeleteReference::SEARCH_REFERENCE);
	ta_uint32 dgnaRef = convertTextToSubscriberReference(dgnaTextRef);

	// Query current subscribers in dgna
	ta_uint32 groupResultSet = performSubscriberSearch("PARENT='" + m_sessionDGNAITSI + "'"
		                                                   ,RadioMethodSearchSubscribers::K_MEMBERS);
	std::vector<std::string> dgnaSubscribersTextRef = queryResultsAsList(groupResultSet,RadioMethodQueryReference::K_MEMBERS);
	deleteReference(groupResultSet,RadioMethodDeleteReference::SEARCH_REFERENCE);

	unsigned int iLoop;
	// Determine the subscribers to remove
	std::string changeText = "";
	for (iLoop=0;iLoop<dgnaSubscribersTextRef.size();iLoop++)
	{
		// Check if this subscriber is in the new dest TSI list
		if (changeText.size()>0) changeText += ",";
		changeText += "-" + dgnaSubscribersTextRef.at(iLoop);
	}

	// Update the subscriber record
	// Update the subscriber record
	// If the changeText is empty then there is nothing to change. Don't do a changeReference because it will fail
	if(!changeText.empty())
	{
		RadioMethodChangeReference changeReferenceMethod(getValidSessionRef(),dgnaRef);
		changeReferenceMethod.setGroupMembers(changeText);
		RadioEvent* reply = sendMethod(changeReferenceMethod);
		delete reply;
		reply = NULL;
	}

    FUNCTION_EXIT;
}

// no longer in use, directed to startGroupMonitoring instead
ta_uint32 RadioSession::startMonitoring(const char * tsi)
{
    FUNCTION_ENTRY("startMonitoring()");

    LOG_GENERIC(SourceInfo, DebugUtil::DebugDebug, "startMonitoring(TSI %s)", tsi);

	ta_uint32 retVal = 0;
    RadioEvent * event = NULL;

    try
    {
        RadioMethodMonitorSubscriber monitorMethod(m_sessionRef, tsi, RadioMethodMonitorSubscriber::MON_START);
        event = sendMethod(monitorMethod, tsi);
    
        MonitorSubscriberEventReader * mser = dynamic_cast<MonitorSubscriberEventReader *>(event->getEventReader());
        // Remove to avoid crash
		//TA_ASSERT( mser!=0 , "EventReader not for MonitorSubscriber" );
		if (0 == mser)
		{
			LOG0(SourceInfo, TA_Base_Core::DebugUtil::DebugError, "Invalid response received for RadioMethodMonitorSubscriber!");
			throw;
		}

		retVal = mser->getMonitorReference();

        m_radioTcpServer.getSubscriberMonitor().addMonitor(retVal, event->getSessionRef(), tsi);

        delete event;
        event = NULL;
    }
    catch (...)
    {
		if (0 != event) {
			delete event;
			event = NULL;
		}
        throw;
    }

    FUNCTION_EXIT;
	return retVal;
}

// no longer in use, directed to stopGroupMonitoring instead
void RadioSession::stopMonitoring(const char * tsi)
{
    FUNCTION_ENTRY("stopMonitoring()");

    LOG_GENERIC(SourceInfo, DebugUtil::DebugDebug, "stopMonitoring(TSI %s)", tsi);
    
    RadioEvent * event = NULL;

    try
    {
        MonitorReference monRef = m_radioTcpServer.getSubscriberMonitor().findMonitor(tsi);
        if (0==monRef)
        {
            LOG_GENERIC(SourceInfo, DebugUtil::DebugDebug, "stopMonitoring could not find Monitor for subscriber %s", tsi);
            return;
        }

        // ///////////////////////
        // MonitorSubscriber(MON_STOP)
        RadioMethodMonitorSubscriber monitorMethod(m_sessionRef, tsi, RadioMethodMonitorSubscriber::MON_STOP, monRef);
        event = sendMethod(monitorMethod, tsi);
    
        delete event;
        event = NULL;

        m_radioTcpServer.getSubscriberMonitor().removeMonitor(monRef);

        // ///////////////////////
        // DeleteReference(MonitorReference)
        RadioMethodDeleteReference delRefMethod(m_sessionRef);
        delRefMethod.setReference(RadioMethodDeleteReference::MONITOR_REFERENCE,monRef);
        event = sendMethod(delRefMethod);
    
        delete event;
        event = NULL;
    }
    catch (...)
    {
        delete event;
        event = NULL;
        throw;
    }

    FUNCTION_EXIT;
}

