void RadioSession::addCallToHistory(std::string sessionId, const TA_IRS_App::CallDetailsType &details)
{
	FUNCTION_ENTRY("addCallToHistory");
	// Retrieve the necessary details needed to create the history item

	// Retrieve the radio call details
	std::string identifier;
	std::string location;
	std::string itsi;
	time_t		ttime = RadioHelper::getCurrentTime();
	TA_Base_Bus::IRadioCorbaDef::EOriginType originType;
	if (details.callSource == TA_IRS_App::OutgoingCall)
	{
		originType = TA_Base_Bus::IRadioCorbaDef::OUTBOUND;
		identifier = details.calledName;
		location = details.calledLocation;
		itsi = details.calledTSI;
	}
	else
	{
		originType = TA_Base_Bus::IRadioCorbaDef::INBOUND;
		identifier = details.callerName;
		location = details.callerLocation;
		itsi = details.callerTSI;
	}

	TA_Base_Bus::IRadioCorbaDef::EStackCallType type = TA_Base_Bus::IRadioCorbaDef::CALL_INVALID;

	if (details.callStatus != TA_Base_Bus::IRadioCorbaDef::Ringing)
	{
		type = TA_Base_Bus::IRadioCorbaDef::ENDED;
	}
	else if (details.callSource == TA_Base_Bus::IRadioCorbaDef::IncomingCall)
	{
		type = TA_Base_Bus::IRadioCorbaDef::MISSED;
	}
	else
	{
		type = TA_Base_Bus::IRadioCorbaDef::FAILED;
	}

	addCallToHistory(sessionId, ttime, originType, type,
		identifier, itsi, location, details.isEmergency);

	FUNCTION_EXIT;
	return;
}

void RadioSession::addCallToHistory(std::string sessionId,
	const time_t& timestamp,
	TA_Base_Bus::IRadioCorbaDef::EOriginType originType,
	TA_Base_Bus::IRadioCorbaDef::EStackCallType callType,
	const std::string& identifier,
	const std::string& itsi,
	const std::string& location,
	bool isEmergency)
{
	FUNCTION_ENTRY("addCallToHistory");

	LOG_GENERIC(SourceInfo, TA_Base_Core::DebugUtil::DebugDebug,
		"hongzhi, addCallToHistory() - RadioTcpServer %d (CRS%d) Session %lu adding Call History (sessionProfileName:%s, timestamp:%ld, ID:%s, TSI:%s, location:%s",
		m_radioTcpServer.getServerIndex(), m_radioTcpServer.getCRSNumber(), m_sessionRef, m_taSessionProfileName.c_str(), timestamp, identifier.c_str(), itsi.c_str(), location.c_str());

	if (m_sessionId != sessionId) // only retrieve session information once
	{
		// Retrieve the TransActive session details
		updateTASession(sessionId);
	}

	std::string strIdentifier = identifier;
	std::string strTsi = itsi;
	std::string strLoc = location;

	if (0 >= identifier.length())
	{
		strIdentifier = "Unknown";
	}
	if (0 >= itsi.length())
	{
		strTsi = "Unknown";
	}

	std::string taSessionProfileName = "";
	{
		//todo lock  m_taSessionProfileName
		TA_Base_Core::ThreadGuard lock(m_iscsSessionInfolock);
		taSessionProfileName = m_taSessionProfileName;
	}

	m_radioTcpServer.getRadio().addCallStackEntry(taSessionProfileName.c_str(),
		m_radioSessionServant.getEntityLocationKey(),
		timestamp,
		originType,
		callType,
		strIdentifier.c_str(),
		strLoc.c_str(),
		isEmergency,
		itsi.c_str());

	FUNCTION_EXIT;
	return;
}

std::string RadioSession::getProfileFromSessionId(std::string sessionId)
{
	std::string profileName;
	TA_Base_Core::IProfile* profile;
	try
	{
		TA_Base_Bus::AuthenticationLibrary  authLib;

		TA_Base_Bus::SessionInfo sessionInfo = authLib.getSessionInfo(sessionId, sessionId);

		profile = TA_Base_Core::ProfileAccessFactory::getInstance().getProfile(sessionInfo.ProfileId[0]);
		profileName = profile->getName();
		delete profile;
		profile = NULL;
	}
	catch (...)
	{
		delete profile;
		profile = NULL;
	}

	return profileName;
}

void RadioSession::updateTASession(const std::string& sessionID)
{
	FUNCTION_ENTRY("updateTASession");
	TA_Base_Core::IProfile*  profile = NULL;
	try
	{
		TA_Base_Bus::AuthenticationLibrary  authLib;

		TA_Base_Bus::SessionInfo sessionInfo = authLib.getSessionInfo(sessionID, sessionID);
		profile = TA_Base_Core::ProfileAccessFactory::getInstance().getProfile(sessionInfo.ProfileId[0]);
		if (0 != profile)
		{
			TA_Base_Core::ThreadGuard lock(m_iscsSessionInfolock);
			m_taSessionProfileName = profile->getName();
		}
		else
		{
			LOG1(SourceInfo, TA_Base_Core::DebugUtil::DebugWarn,
				"No profile found for session %s", sessionID.c_str());

		}
		delete profile;
		profile = NULL;
		m_sessionId = sessionID;
		LOG1(SourceInfo, TA_Base_Core::DebugUtil::DebugInfo, "Update TA Session with sessionID=%s", m_sessionId.c_str());
	}
	catch (...)
	{
		LOG_GENERIC(SourceInfo, TA_Base_Core::DebugUtil::DebugError, "Could not determine sessionInfo for sessionId %s", m_sessionId.c_str());
		if (NULL != profile)
			delete profile;
	}

	FUNCTION_EXIT;
}

