ta_uint32 RadioSession::startGroupMonitoring(const char * tsi)
{
	FUNCTION_ENTRY("startGroupMonitoring");
	MonitorReference monitoredID = time(0);
	std::string groupTSI = tsi;

	LOG2(SourceInfo, TA_Base_Core::DebugUtil::DebugInfo, " Start Group Monitoring for TSI = %s with assigned monitor ID = %d", tsi, monitoredID);

	// check if there is an existing call
	TA_IRS_App::CallDetailsType callDetails = m_radioTcpServer.findActiveCall(groupTSI);

	// check if already monitored
	T_MonitoredGroup::iterator itrFind = m_monitoredGroups.find(groupTSI);

	if (itrFind != m_monitoredGroups.end())
	{	// 
		monitoredID = itrFind->second.monitorID;
		LOG2(SourceInfo, TA_Base_Core::DebugUtil::DebugInfo, "Group TSI = %s already monitored with assigned monitor ID = %d", tsi, monitoredID);
	}
	else
	{
		LOG2(SourceInfo, TA_Base_Core::DebugUtil::DebugInfo, "Group TSI = %s added to monitored list with assigned monitor ID = %d", tsi, monitoredID);
		m_monitoredGroups.insert(T_MonitoredGroup::value_type(groupTSI, { callDetails.callID, monitoredID, groupTSI}));
	}
	
	if (callDetails.callID != 0 && 
		(/*callDetails.callType != SingleCall
			&&*/ callDetails.callSource == IncomingCall
			&& callDetails.callStatus == Ringing))
	{	// Call found // then we need to answer call
		LOG2(SourceInfo, TA_Base_Core::DebugUtil::DebugInfo, " Found existing call for Group TSI = %s, callID=%d, auto answering call", tsi, callDetails.callID);
		answerCall(callDetails.callID, "", true); 
	}
	else
	{	// Peform setup call to test for existing call
		LOG2(SourceInfo, TA_Base_Core::DebugUtil::DebugInfo, " No existing call for Group TSI = %s, callID=%d, trigger test call", tsi, callDetails.callID);
		testGroupCall(groupTSI);
	}


	FUNCTION_EXIT;
	return monitoredID;
}

void RadioSession::stopGroupMonitoring(const char * tsi)
{
	FUNCTION_ENTRY("stopGroupMonitoring");
	std::string groupTSI = tsi;

	LOG1(SourceInfo, TA_Base_Core::DebugUtil::DebugInfo, " Stop Group Monitoring for TSI = %s", tsi);

	T_MonitoredGroup::iterator itrFind = m_monitoredGroups.find(groupTSI);
	if (itrFind != m_monitoredGroups.end())
	{	// Found
		TA_IRS_App::CallDetailsType callDetails = m_radioTcpServer.findActiveCall(groupTSI);
		if (callDetails.callID != 0 &&
			(/*callDetails.callType != SingleCall
				&& */(callDetails.callStatus == Connected
				|| callDetails.callStatus == ConnectedGroup)))
		{	// Call found // then we need to answer call
			// Release the audio and disconnect from the call
			LOG_GENERIC(SourceInfo, TA_Base_Core::DebugUtil::DebugDebug,
				"RadioSession::releaseCall - releasing Audio references, Session %lu Call %lu",
				getValidSessionRef(), callDetails.callID);

			m_radioTcpServer.getRadioResourceManager().releaseAudioReference(getValidSessionRef(), callDetails.callID, m_radioTcpServer.getSubscriberMonitor().isListenCall(callDetails.callID));

			// Disconnect the call!
			LOG_GENERIC(SourceInfo, TA_Base_Core::DebugUtil::DebugDebug,
				"RadioSession::releaseCall - calling RadioMethodDisconnect, Session %lu Call %lu",
				getValidSessionRef(), callDetails.callID);

			RadioMethodDisconnect disconnectMethod(getValidSessionRef(), callDetails.callID);
			RadioEvent* event = sendMethod(disconnectMethod);
			delete event;
			event = 0;

			// Release the associated call reference
			deleteReference(callDetails.callID, RadioMethodDeleteReference::CALL_REFERENCE);
			LOG_GENERIC(SourceInfo, TA_Base_Core::DebugUtil::DebugDebug,
				"RadioSession::releaseCall - Deleted CallReference, Session %lu Call %lu",
				getValidSessionRef(), callDetails.callID);
		}

		// Finally remove it from the monitored groups
		m_monitoredGroups.erase(itrFind);

	}
	else
	{
		LOG1(SourceInfo, TA_Base_Core::DebugUtil::DebugError, "Unable to find GroupTSi=%s from the monitored group items.", tsi);
	}

	FUNCTION_EXIT;
}

bool RadioSession::isGroupMonitored(const std::string& groupTSI)
{
	FUNCTION_ENTRY("isGroupMonitored");
	bool bRetVal = false;

	T_MonitoredGroup::iterator itrFind = m_monitoredGroups.find(groupTSI);
	if (itrFind != m_monitoredGroups.end())
	{
		bRetVal = true;
	}

	if (!bRetVal)
	{	// Not Found // try checking for patch TSI
		std::string tempPathTSI = groupTSI;
		if (groupTSI.find('-') != std::string::npos)
			tempPathTSI = groupTSI.substr(0, groupTSI.find_first_of('-'));

		itrFind = m_monitoredGroups.find(tempPathTSI);
		if (itrFind != m_monitoredGroups.end())
		{
			bRetVal = true;
		}
	}

	FUNCTION_EXIT;
	return bRetVal;
}

ta_int32 RadioSession::testGroupCall(const std::string & groupTSI)
{
	FUNCTION_ENTRY("isGroupMonitored");
	RadioReference callReference = 0;
	try
	{
		RadioMethodSetupCall::ECallType callType = RadioMethodSetupCall::GROUP_UNACKNOWLEDGE;
		ECallCategory  category = HalfDuplex;

		// Get a new call reference (to be deleted when the call disconnects)
		
		callReference = getNewReference(RadioMethodNewReference::CALL_REFERENCE);

		// Setup the call (note we might get an unsolicited CallStatus event in addition to the Setup call event)
		RadioMethodSetupCall   setupMethod(getValidSessionRef(), callReference);
		setupMethod.setCallDestination(groupTSI);
		setupMethod.setCallType(callType);
		setupMethod.setFullDuplex(false);
		setupMethod.setCallPriority(Priority0);
		setupMethod.setHookBit(true);
		setupMethod.setRequestTx(RadioMethodSetupCall::NO_REQUEST_TX);
		//setupMethod.setCommunicationType(RadioMethodSetupCall::CMT_Speech)

		RadioEvent* reply = sendMethod(setupMethod, groupTSI);
		delete reply;

		// Attach some audio to the call // Assign to left speaker
		m_radioTcpServer.getRadioResourceManager().attachAudio(getValidSessionRef(), callReference);
		m_radioTcpServer.getRadioResourceManager().setAudioSpeaker
		(getValidSessionRef(), callReference, LeftSpeaker, 0, RadioMethodChangeReference::MicOff);


		// Add a new call to the stack
		CallDetailsType details;
		// CallDetailsType  details;

		details.callStatus = Connected;
		details.callSource = IncomingCall;
		details.callCategory = category;
		details.callType = GroupUnacknowledgeCall;
		// details.callTime     = getCurrentTime();  // set by radio

		// Get the call details from the event
		details.callID = callReference;
		details.sessionRef = getValidSessionRef();
		details.calledTSI = groupTSI;
		details.callerTSI = getSessionTSI();

		details.isEmergency = false;
		//TD 10234
		details.isInvisibleToGUIApps = false;
		details.isIncludeCall = false;
		details.callerLocation = TA_Base_Core::LocationAccessFactory::getInstance().getLocationByKey(m_locationKey)->getName();
		
		// add call to call stack before doing any more queries
		if (callType != GroupAcknowledgeCall)
		{
			// This both looks up the caller/called details and adds to the callstack
			m_radioTcpServer.addBackgroundTask(RadioTaskFactory::createCallStackUpdateTask(&m_radioTcpServer, details, m_DefaultEmergencyCallPriority));
		}
		else
		{
			// must wait for a suitable GroupCallAck event before proceeding...
			m_radioTcpServer.addPendingGroupCallAck(details);
		}

	}
	catch (RadioSessionException& e)
	{
		// Error excuting the command
		// Should not throw error for negative 14
		if (e.getErrorNumber() == STATUS_KO_SETUP_CALL_FAILED) // -14
			LOG1(SourceInfo, TA_Base_Core::DebugUtil::DebugDebug, "Setup call failed! Group TSI %s has no active call", groupTSI.c_str());
		else
			throw TA_Base_Bus::IRadioSessionCorbaDef::radioAPIException(e.what());

	}
	catch (RadioSessionNotInitialisedException&)
	{
		throw TA_Base_Bus::IRadioSessionCorbaDef::sessionNotInitialiseException();
	}
	catch (RadioException& e)
	{
		// catch all radio exceptions
		throw TA_Base_Bus::IRadioSessionCorbaDef::radioAPIException(e.what());
	}

	FUNCTION_EXIT;
	return callReference;
}

std::string RadioSession::formatString(std::string& raData)
{
	FUNCTION_ENTRY("formatString()");
	TA_IRS_Bus::Ucs2CharacterEncoding charEncoder;
	std::string mbsString(raData.begin(), raData.end());

	// Convert to wide string
	std::wstring wideString = charEncoder.convertText(mbsString);

	MessageTextType finalTextMsg;
	LOG1(SourceInfo, TA_Base_Core::DebugUtil::DebugDebug, "Processing wide string with Size %d", wideString.size());

	// Format all string
	for (std::wstring::const_iterator textIter = wideString.begin();
		textIter != wideString.end(); ++textIter)
	{
		unsigned short value = (unsigned short)*(textIter);
		LOG1(SourceInfo, TA_Base_Core::DebugUtil::DebugDebug, "Processing wide character with value %d", value);

		unsigned char lowerByte, upperByte;

		if (is_little_endian())
		{
			upperByte = (unsigned char)(value >> 8); // retrieve the higher byte
			lowerByte = (unsigned char)(value & 0xff); // retrieve the lower byte
		}
		else
		{
			upperByte = (unsigned char)(value & 0xff); // retrieve the upper byte
			lowerByte = (unsigned char)(value >> 8); // retrieve the lower byte
		}

		// Motorola is formatted in BigEndian
		finalTextMsg.push_back(upperByte);
		finalTextMsg.push_back(lowerByte);
	}

	FUNCTION_EXIT;
	return std::string(finalTextMsg.begin(), finalTextMsg.end());
}